def pagoda(mods=8):
    prof = [[0, 1.15], [0.17, 0.95]]
    for i in range(mods):
        a, b = 0.18 + i * 0.08, 0.18 + (i + 1) * 0.08
        prof += [[a, 0.72], [b - 0.005, 0.98]]
    return prof + [[0.83, 0.55], [1.0, 0.35]]


